const { validatePluginName } = require('../../../../src/plugins/shape/name');

describe('validatePluginName', () => {
  test('returns a new plugin object with fullName and preserves original properties', () => {
    const input = { name: 'myplugin', version: '1.0.0', enabled: true };
    const result = validatePluginName(input);

    // Should return a new object, not mutate the original
    expect(result).toBeInstanceOf(Object);
    expect(result).not.toBe(input);

    // Original properties should be preserved
    expect(result.name).toBe(input.name);
    expect(result.version).toBe(input.version);
    expect(result.enabled).toBe(input.enabled);

    // Should include fullName property derived from name
    expect(result).toHaveProperty('fullName');
    expect(typeof result.fullName).toBe('string');
    expect(result.fullName.endsWith(input.name)).toBe(true);
  });

  test('throws TypeError when plugin object has no name property', () => {
    expect(() => validatePluginName({})).toThrow(TypeError);
  });

  test('throws TypeError when name is not a string', () => {
    expect(() => validatePluginName({ name: 123 })).toThrow(TypeError);
    expect(() => validatePluginName({ name: null })).toThrow(TypeError);
    expect(() => validatePluginName({ name: undefined })).toThrow(TypeError);
  });

  test('throws TypeError when plugin is null', () => {
    expect(() => validatePluginName(null)).toThrow(TypeError);
  });

  test('is synchronous (not returning a Promise)', () => {
    const input = { name: 'myplugin' };
    const result = validatePluginName(input);
    expect(result).toBeDefined();
    // Ensure it's not a thenable
    expect(typeof result.then).toBe('undefined');
  });
});

