    expect(() => shouldPrefixCause(null, Error)).toThrow(TypeError);
    expect(() => shouldPrefixCause(undefined, Error)).toThrow(TypeError);
    expect(() => shouldPrefixCause(123, Error)).toThrow(TypeError);
  });

  test('throws TypeError when error has no cause property', () => {
    const error = new Error('outer');
    delete error.cause;
    expect(() => shouldPrefixCause(error, Error)).toThrow(TypeError);
  });

  test('does not throw when ErrorClass is not a function and returns false', () => {
    const error = new Error('outer');
    error.cause = new Error('cause');
    expect(() => shouldPrefixCause(error, {})).not.toThrow();
    expect(shouldPrefixCause(error, {})).toBe(false);
  });

  test('returns false when cause has a useful name that matches ErrorClass', () => {
    const cause = new Error('cause');
    cause.name = 'Error'; // matches Error.name
    const error = new Error('outer');
    error.cause = cause;

    expect(shouldPrefixCause(error, Error)).toBe(false);
  });

  test('returns true when cause name differs from its constructor name', () => {
    const cause = new Error('cause');
    cause.name = 'MyCustomError';
    const error = new Error('outer');
    error.cause = cause;

    // cause.constructor.name is 'Error'; cause.name 'MyCustomError' != 'Error'
    expect(shouldPrefixCause(error, TypeError)).toBe(true);
  });

  test('returns false when cause name is undefined or equals constructor name and does not match ErrorClass', () => {
    const cause = new Error('cause');
    delete cause.name; // cause.name becomes undefined
    const error = new Error('outer');
    error.cause = cause;

    expect(shouldPrefixCause(error, Error)).toBe(false);
  });

  test('does not modify error or cause objects', () => {
    const cause = new Error('cause');
    cause.name = 'CustomCause';
    const error = new Error('outer');
    error.cause = cause;

    const errorSnapshot = { name: error.name, message: error.message, cause: error.cause };
    const causeSnapshot = { name: cause.name, message: cause.message };

    shouldPrefixCause(error, Error);

    expect(error.name).toBe(errorSnapshot.name);
    expect(error.message).toBe(errorSnapshot.message);
    expect(error.cause).toBe(errorSnapshot.cause);
    expect(cause.name).toBe(causeSnapshot.name);
    expect(cause.message).toBe(causeSnapshot.message);
  });

  test('returns false when cause is not an object even if name exists', () => {
    const cause = 'not-an-error';
    const error = new Error('outer');
    error.cause = cause;

    expect(shouldPrefixCause(error, Error)).toBe(false);
  });
});

