const path = require('path');

describe('normalizePlugin', () => {
  let normalizePlugin;
  class FakeParentError extends Error {
    constructor(message) {
      super(message);
      this.name = 'FakeParentError';
    }
  }

  beforeAll(() => {
    const modPath = path.resolve(__dirname, '../../../../src/plugins/shape/main.js');
    const mod = require(modPath);
    normalizePlugin = mod?.normalizePlugin ?? mod;
  });

  test('throws when plugin is not an object, using ParentError name', () => {
    expect(() => normalizePlugin(123, FakeParentError)).toThrow();
    try {
      normalizePlugin(123, FakeParentError);
    } catch (e) {
      expect(e.name).toBe('FakeParentError');
    }
  });

  test('throws when plugin lacks a valid name', () => {
    const invalidNamePlugin = { methods: {} };
    expect(() => normalizePlugin(invalidNamePlugin, FakeParentError)).toThrow();
    try {
      normalizePlugin(invalidNamePlugin, FakeParentError);
    } catch (e) {
      expect(e.name).toBe('FakeParentError');
    }
  });

  test('throws when plugin name is not a string', () => {
    const invalidTypeNamePlugin = { name: 123, methods: {} };
    expect(() => normalizePlugin(invalidTypeNamePlugin, FakeParentError)).toThrow();
    try {
      normalizePlugin(invalidTypeNamePlugin, FakeParentError);
    } catch (e) {
      expect(e.name).toBe('FakeParentError');
    }
  });

  test('normalizes a valid plugin and does not mutate input, and defaults options', () => {
    const plugin = {
      name: 'MyPlugin',
      methods: {
        start() {
          return 'started';
        }
      }
    };

    const normalized = normalizePlugin(plugin, FakeParentError);

    expect(normalized).toBeTruthy();
    expect(normalized).toBeInstanceOf(Object);
    expect(normalized).toHaveProperty('name', 'MyPlugin');
    expect(normalized).toHaveProperty('methods');
    expect(typeof normalized.methods.start).toBe('function');
    // Ensure input object is not mutated to add options
    expect(plugin).not.toHaveProperty('options');
  });

  test('returns plain object and provides default empty options when missing', () => {
    const plugin = {
      name: 'OnlyName',
      methods: {}
    };

    const normalized = normalizePlugin(plugin, FakeParentError);

    expect(normalized).toBeInstanceOf(Object);
    expect(normalized.constructor).toBe(Object);
    expect(normalized).toHaveProperty('name', 'OnlyName');
    expect(normalized).toHaveProperty('options');
    expect(normalized.options).toEqual({});
  });
});

